from pypdf import PdfReader
import io
import concurrent.futures
import urllib.request

def fetch_pdf(num):
    url = f"https://www.tms.org/tms2027/downloads/flyers/TMS2027-CFA-Flyer-{num:03d}.pdf"
    try:
        req = urllib.request.Request(url, headers={"User-Agent":"Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=20) as r:
            return num, r.read()
    except Exception as e:
        return num, None

with concurrent.futures.ThreadPoolExecutor(max_workers=20) as ex:
    pdf_results = list(ex.map(fetch_pdf, range(1, 107)))

print(f"Downloaded {sum(1 for n,d in pdf_results if d)} flyers")

flyers = {}
for num, data in pdf_results:
    if not data:
        continue
    try:
        rdr = PdfReader(io.BytesIO(data))
        text = "\n".join(p.extract_text() for p in rdr.pages[:1])
        flyers[num] = text
    except Exception as e:
        flyers[num] = f"ERR: {e}"

print(len(flyers))

